_polygolappStrings.JA = _polygolappStrings.JP;

const _bcp47Map = {
    'EN': 'en-US',
    'JP': 'ja-JP',
    'JA': 'ja-JP',
    'KO': 'ko-KR',
    'ZH': 'zh-CN'
};

function _getBcp47Locale(langCode) {
    const code = (langCode || 'EN').toUpperCase();
    return _bcp47Map[code] || 'en-US';
}

// System Global Locale State
const _systemLocaleState = {
    languageCode: 'EN',
    locale: 'en-US',
    dateFormat: 'auto',
    use12HourFormat: false,
    timeZone: 'auto'
};
const _localeChangeListeners = new Set();

// Read initial locale settings from localStorage if accessible
try {
    const storedLang = localStorage.getItem('selectedLanguage');
    if (storedLang && storedLang !== 'auto') {
        const norm = (storedLang === 'JA' || storedLang === 'JP') ? 'JP' : (['KO', 'ZH'].includes(storedLang) ? storedLang : 'EN');
        _systemLocaleState.languageCode = norm;
        _systemLocaleState.locale = _getBcp47Locale(norm);
    } else if (!isInsidePolygol) {
        const detected = _detectSystemLanguage();
        _systemLocaleState.languageCode = detected;
        _systemLocaleState.locale = _getBcp47Locale(detected);
    }
    const storedDateFormat = localStorage.getItem('systemDateFormat') || localStorage.getItem('dateFormatPreference');
    if (storedDateFormat) _systemLocaleState.dateFormat = storedDateFormat;
    const stored12Hour = localStorage.getItem('use12HourFormat');
    if (stored12Hour !== null) _systemLocaleState.use12HourFormat = (stored12Hour === 'true');
    const storedTz = localStorage.getItem('timeZoneSelection');
    if (storedTz) _systemLocaleState.timeZone = storedTz;
} catch (e) {}

// System Global Layout & Padding State
const _systemLayoutState = {
    topScreenPadding: '80px',
    bottomScreenPadding: '80px',
    sideScreenPadding: '16px',
    leftScreenPadding: '16px',
    rightScreenPadding: '16px',
    statusBarHeight: '80px',
    dockHeight: '80px',
    screenCurve: '0px'
};
const _layoutChangeListeners = new Set();

function _parsePx(val, fallback = 0) {
    if (typeof val === 'number') return val;
    if (typeof val === 'string') {
        const parsed = parseFloat(val);
        return isNaN(parsed) ? fallback : parsed;
    }
    return fallback;
}

function _getScreenPadding() {
    const cs = window.getComputedStyle ? window.getComputedStyle(document.documentElement) : null;
    const topVal = cs ? cs.getPropertyValue('--top-screen-padding').trim() : _systemLayoutState.topScreenPadding;
    const bottomVal = cs ? cs.getPropertyValue('--bottom-screen-padding').trim() : _systemLayoutState.bottomScreenPadding;
    const sideVal = cs ? cs.getPropertyValue('--side-screen-padding').trim() : _systemLayoutState.sideScreenPadding;
    const leftVal = cs ? (cs.getPropertyValue('--left-screen-padding').trim() || sideVal) : _systemLayoutState.leftScreenPadding;
    const rightVal = cs ? (cs.getPropertyValue('--right-screen-padding').trim() || sideVal) : _systemLayoutState.rightScreenPadding;

    return {
        top: _parsePx(topVal, 80),
        bottom: _parsePx(bottomVal, 80),
        side: _parsePx(sideVal, 16),
        left: _parsePx(leftVal, 16),
        right: _parsePx(rightVal, 16),
        raw: {
            top: topVal || '80px',
            bottom: bottomVal || '80px',
            side: sideVal || '16px',
            left: leftVal || '16px',
            right: rightVal || '16px'
        }
    };
}

function _getInsets() {
    const pad = _getScreenPadding();
    return {
        top: pad.top,
        bottom: pad.bottom,
        left: pad.left,
        right: pad.right
    };
}

function _applySystemLayoutVariables(variables) {
    if (!variables || typeof variables !== 'object') return;
    Object.entries(variables).forEach(([k, v]) => {
        document.documentElement.style.setProperty(k, v);
        if (k === '--top-screen-padding') _systemLayoutState.topScreenPadding = v;
        else if (k === '--bottom-screen-padding') _systemLayoutState.bottomScreenPadding = v;
        else if (k === '--side-screen-padding') _systemLayoutState.sideScreenPadding = v;
        else if (k === '--left-screen-padding') _systemLayoutState.leftScreenPadding = v;
        else if (k === '--right-screen-padding') _systemLayoutState.rightScreenPadding = v;
        else if (k === '--status-bar-height') _systemLayoutState.statusBarHeight = v;
        else if (k === '--dock-height') _systemLayoutState.dockHeight = v;
        else if (k === '--screen-curve') _systemLayoutState.screenCurve = v;
    });

    const detail = {
        variables: { ...variables },
        padding: _getScreenPadding(),
        insets: _getInsets()
    };

    const evt = new CustomEvent('PolygolLayoutChange', { detail });
    window.dispatchEvent(evt);

    _layoutChangeListeners.forEach(listener => {
        try {
            listener(detail);
        } catch (err) {
            console.error('[APPAPI] Layout listener error:', err);
        }
    });
}

function _applySystemLocale(payload) {
    if (!payload || typeof payload !== 'object') return;
    let changed = false;

    if (payload.languageCode) {
        let code = payload.languageCode;
        if (code === 'auto') {
            code = _detectSystemLanguage();
        }
        const norm = (code === 'JA' || code === 'JP') ? 'JP' : 
            (['KO', 'ZH'].includes(code) ? code : 'EN');
        if (_systemLocaleState.languageCode !== norm) {
            _systemLocaleState.languageCode = norm;
            _systemLocaleState.locale = payload.locale || _getBcp47Locale(norm);
            changed = true;
        }
    }
    if (payload.locale && _systemLocaleState.locale !== payload.locale) {
        _systemLocaleState.locale = payload.locale;
        changed = true;
    }
    if (payload.dateFormat && _systemLocaleState.dateFormat !== payload.dateFormat) {
        _systemLocaleState.dateFormat = payload.dateFormat;
        changed = true;
    }
    if (payload.use12HourFormat !== undefined) {
        const b = (payload.use12HourFormat === true || payload.use12HourFormat === 'true');
        if (_systemLocaleState.use12HourFormat !== b) {
            _systemLocaleState.use12HourFormat = b;
            changed = true;
        }
    }
    if (payload.timeZone !== undefined && _systemLocaleState.timeZone !== payload.timeZone) {
        _systemLocaleState.timeZone = payload.timeZone;
        changed = true;
    }

    if (document.documentElement) {
        document.documentElement.lang = _systemLocaleState.locale;
    }

    // Automatically translate DOM elements with data-lang attributes
    try {
        const langDict = _polygolappStrings[_systemLocaleState.languageCode] || _polygolappStrings.EN || {};
        if (typeof document !== 'undefined' && document.querySelectorAll) {
            document.querySelectorAll('[data-lang-key]').forEach(el => {
                const key = el.getAttribute('data-lang-key');
                if (langDict[key]) el.textContent = langDict[key];
            });
            document.querySelectorAll('[data-lang-placeholder]').forEach(el => {
                const key = el.getAttribute('data-lang-placeholder');
                if (langDict[key]) el.placeholder = langDict[key];
            });
            document.querySelectorAll('[data-lang-title]').forEach(el => {
                const key = el.getAttribute('data-lang-title');
                if (langDict[key]) el.title = langDict[key];
            });
            document.querySelectorAll('[data-lang-aria-label]').forEach(el => {
                const key = el.getAttribute('data-lang-aria-label');
                if (langDict[key]) el.setAttribute('aria-label', langDict[key]);
            });
        }
    } catch (e) {}

    const detail = { ..._systemLocaleState };
    const evt = new CustomEvent('PolygolLocaleChange', { detail });
    window.dispatchEvent(evt);

    _localeChangeListeners.forEach(listener => {
        try {
            listener(detail);
        } catch (err) {
            console.error('[APPAPI] Locale listener error:', err);
        }
    });
}

function _parseDate(dateInput) {
    if (!dateInput && dateInput !== 0) return new Date();
    if (dateInput instanceof Date) return dateInput;
    if (typeof dateInput === 'number' || typeof dateInput === 'string') {
        const d = new Date(dateInput);
        if (!isNaN(d.getTime())) return d;
    }
    return new Date();
}

function _formatDate(dateInput, formatOverride) {
    const d = _parseDate(dateInput);
    const fmt = formatOverride || _systemLocaleState.dateFormat || 'auto';
    const loc = _systemLocaleState.locale || 'en-US';

    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');

    switch (fmt) {
        case 'YYYY-MM-DD':
            return `${yyyy}-${mm}-${dd}`;
        case 'DD/MM/YYYY':
            return `${dd}/${mm}/${yyyy}`;
        case 'MM/DD/YYYY':
            return `${mm}/${dd}/${yyyy}`;
        case 'medium':
            return new Intl.DateTimeFormat(loc, { year: 'numeric', month: 'short', day: 'numeric' }).format(d);
        case 'long':
            return new Intl.DateTimeFormat(loc, { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }).format(d);
        case 'auto':
        default:
            return new Intl.DateTimeFormat(loc, { year: 'numeric', month: 'numeric', day: 'numeric' }).format(d);
    }
}

function _formatTime(dateInput, options = {}) {
    const d = _parseDate(dateInput);
    const loc = _systemLocaleState.locale || 'en-US';
    const is12 = options.hour12 !== undefined ? options.hour12 : _systemLocaleState.use12HourFormat;
    
    const intlOpts = {
        hour: 'numeric',
        minute: 'numeric',
        hour12: is12,
        ...options
    };
    if (options.includeSeconds) {
        intlOpts.second = 'numeric';
        delete intlOpts.includeSeconds;
    }
    if (_systemLocaleState.timeZone && _systemLocaleState.timeZone !== 'auto') {
        if (!intlOpts.timeZone) intlOpts.timeZone = _systemLocaleState.timeZone;
    }

    return new Intl.DateTimeFormat(loc, intlOpts).format(d);
}

function _formatDateTime(dateInput, dateStyle = null, timeStyle = null) {
    const d = _parseDate(dateInput);
    const formattedDate = _formatDate(d, dateStyle);
    const formattedTime = _formatTime(d, timeStyle ? { timeStyle } : {});
    return `${formattedDate} ${formattedTime}`;
}

function _formatRelativeTime(value, unit = 'day', options = {}) {
    const loc = _systemLocaleState.locale || 'en-US';
    try {
        const rtf = new Intl.RelativeTimeFormat(loc, { numeric: 'auto', ...options });
        return rtf.format(value, unit);
    } catch (e) {
        return `${value} ${unit}s`;
    }
}

function _formatNumber(value, options = {}) {
    const loc = _systemLocaleState.locale || 'en-US';
    return new Intl.NumberFormat(loc, options).format(value);
}

function _formatCurrency(value, currency = 'USD', options = {}) {
    const loc = _systemLocaleState.locale || 'en-US';
    return new Intl.NumberFormat(loc, { style: 'currency', currency, ...options }).format(value);
}

function _getString(key, langOverride) {
    if (!key) return '';
    const lang = (langOverride || _systemLocaleState.languageCode || 'EN').toUpperCase();
    const normLang = (lang === 'JA' || lang === 'JP') ? 'JP' : (['KO', 'ZH'].includes(lang) ? lang : 'EN');
    
    if (_polygolappStrings[normLang] && _polygolappStrings[normLang][key] !== undefined) {
        return _polygolappStrings[normLang][key];
    }
    if (_polygolappStrings.EN && _polygolappStrings.EN[key] !== undefined) {
        return _polygolappStrings.EN[key];
    }
    return key;
}

function _t(key, params = {}, langOverride = null) {
    let str = _getString(key, langOverride);
    if (params && typeof params === 'object') {
        Object.entries(params).forEach(([k, v]) => {
            str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), v);
        });
    }
    return str;
}

// Internal State for Sound
let _autoSoundEnabled = true; // App dev override
let _systemSoundsAllowed = true; // User preference from System
let _isSilentMode = false; // Track system Silent Mode
 
const Polygol = {
  /**
   * Internal helper to send a structured message to the parent window.
   * @param {string} functionName - The name of the Polygol function to call.
   * @param {Array} args - An array of arguments to pass to the function.
   */
  _call: function(functionName, args = []) {
    if (isInsidePolygol) {
      window.parent.postMessage({
        action: 'callPolygolFunc',
        functionName: functionName,
        args: args
      }, '*');
    } else {
      // Use the fallback if it exists, otherwise use the default fallback
      const fallback = _fallbacks[functionName] || (() => _fallbacks.default(functionName));
      fallback.apply(this, args);
    }
  },

  // --- Internationalization and Global Locale Services ---
  intl: {
    getLanguage: function() { return _systemLocaleState.languageCode; },
    getLocale: function() { return _systemLocaleState.locale; },
    getDateFormat: function() { return _systemLocaleState.dateFormat; },
    is12Hour: function() { return _systemLocaleState.use12HourFormat; },
    getTimeZone: function() { return _systemLocaleState.timeZone; },
    getState: function() { return { ..._systemLocaleState }; },
    formatDate: _formatDate,
    formatTime: _formatTime,
    formatDateTime: _formatDateTime,
    formatRelativeTime: _formatRelativeTime,
    formatNumber: _formatNumber,
    formatCurrency: _formatCurrency,
    getString: _getString,
    t: _t,
    getStrings: function(langOverride) {
      const l = (langOverride || _systemLocaleState.languageCode || 'EN').toUpperCase();
      const norm = (l === 'JA' || l === 'JP') ? 'JP' : (['KO', 'ZH'].includes(l) ? l : 'EN');
      return { ...(_polygolappStrings[norm] || _polygolappStrings.EN) };
    },
    onLocaleChange: function(callback) {
      if (typeof callback === 'function') {
        _localeChangeListeners.add(callback);
        try {
          callback({ ..._systemLocaleState });
        } catch (e) {}
        return () => _localeChangeListeners.delete(callback);
      }
      return () => {};
    },
    setLanguage: function(langCode) {
      Polygol._call('selectLanguage', [langCode]);
      _applySystemLocale({ languageCode: langCode });
    },
    setDateFormat: function(format) {
      Polygol._call('setSystemDateFormat', [format]);
      _applySystemLocale({ dateFormat: format });
    }
  },

  // --- System Layout & Environment Information ---
  system: {
    getScreenPadding: _getScreenPadding,
    getInsets: _getInsets,
    getCssVariable: function(varName) {
      const name = varName.startsWith('--') ? varName : `--${varName}`;
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    },
    setCssVariable: function(varName, value) {
      const name = varName.startsWith('--') ? varName : `--${varName}`;
      document.documentElement.style.setProperty(name, value);
    },
    onLayoutChange: function(callback) {
      if (typeof callback === 'function') {
        _layoutChangeListeners.add(callback);
        try {
          callback({
            variables: {
              '--top-screen-padding': `${_getScreenPadding().top}px`,
              '--bottom-screen-padding': `${_getScreenPadding().bottom}px`,
              '--side-screen-padding': `${_getScreenPadding().side}px`,
              '--left-screen-padding': `${_getScreenPadding().left}px`,
              '--right-screen-padding': `${_getScreenPadding().right}px`
            },
            padding: _getScreenPadding(),
            insets: _getInsets()
          });
        } catch (e) {}
        return () => _layoutChangeListeners.delete(callback);
      }
      return () => {};
    },
    getTheme: function() {
      return document.body.classList.contains('light-theme') ? 'light' : 'dark';
    },
    isHighContrast: function() {
      return document.documentElement.classList.contains('polygol-high-contrast');
    }
  },

  // Convenience Aliases for Top-Level Access
  getScreenPadding: _getScreenPadding,
  getInsets: _getInsets,
  onLayoutChange: function(callback) { return Polygol.system.onLayoutChange(callback); },
  getCssVariable: function(name) { return Polygol.system.getCssVariable(name); },
  setCssVariable: function(name, val) { return Polygol.system.setCssVariable(name, val); },
  formatDate: _formatDate,
  formatTime: _formatTime,
  formatDateTime: _formatDateTime,
  formatRelativeTime: _formatRelativeTime,
  formatNumber: _formatNumber,
  formatCurrency: _formatCurrency,
  getString: _getString,
  t: _t,
  onLocaleChange: function(callback) { return Polygol.intl.onLocaleChange(callback); },
  selectLanguage: function(lang) { Polygol.intl.setLanguage(lang); },
  setDateFormat: function(fmt) { Polygol.intl.setDateFormat(fmt); },

  // --- Public API Functions ---

  // --- kirbAI System LLM Services for APPs ---
  ai: {
    /**
     * Prompts the kirbAI LLM to generate text or structured responses.
     * @param {string} promptText - The prompt or question for the AI.
     * @param {object} [options] - Generation options.
     * @returns {Promise<{ text: string, json?: object }>}
     */
    prompt: function(promptText, options = {}) {
      return new Promise((resolve, reject) => {
        const requestId = 'ai_req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
        _aiCallbacks[requestId] = { resolve, reject };

        setTimeout(() => {
          if (_aiCallbacks[requestId]) {
            delete _aiCallbacks[requestId];
            reject(new Error("AI request timed out"));
          }
        }, 30000);

        Polygol._call('aiPrompt', [{ prompt: promptText, options: options, requestId: requestId }]);
      });
    },

    /**
     * Generates a text response using kirbAI.
     * @param {string} promptText
     * @param {object} [options]
     * @returns {Promise<string>}
     */
    generate: function(promptText, options = {}) {
      return this.prompt(promptText, options).then(res => res.text);
    },

    /**
     * Summarizes text using kirbAI.
     * @param {string} text
     * @param {object} [options]
     * @returns {Promise<string>}
     */
    summarize: function(text, options = {}) {
      return this.prompt(text, { ...options, type: 'summarize' }).then(res => res.text);
    },

    /**
     * Generates smart contextual suggestions.
     * @param {object} [context]
     * @returns {Promise<Array>}
     */
    suggest: function(context = {}) {
      return this.prompt('Suggest actions', { ...context, type: 'suggestions' }).then(res => res.json || []);
    },

    /**
     * Parses natural language into structured actions.
     * @param {string} command
     * @param {object} [context]
     * @returns {Promise<object>}
     */
    parse: function(command, context = {}) {
      return this.prompt(command, { ...context, type: 'parse' }).then(res => res.json || null);
    },

    /**
     * Checks if the AI LLM is ready.
     * @returns {Promise<boolean>}
     */
    isReady: function() {
      return new Promise((resolve) => {
        const requestId = 'ai_rdy_' + Date.now();
        _aiCallbacks[requestId] = { resolve, reject: () => resolve(false) };
        Polygol._call('aiIsReady', [{ requestId: requestId }]);
      });
    }
  },

  /**
   * Shows a temporary popup message at the bottom of the screen.
   * @param {string} message - The text to display in the popup.
   */
  showPopup: function(message) {
    this._call('showPopup', [message]);
  },

  /**
   * Shows a more advanced notification on-screen and in the notification shade.
   * @param {string} message - The text to display.
   * @param {object} [options] - Optional parameters.
   * @param {string} [options.icon] - Material Symbols icon name (e.g., 'error', 'check_circle', 'info').
   * @param {string} [options.heading] - Optional heading text to display above the message.
   * @param {string} [options.buttonText] - Optional button text. If provided, a button will be shown.
   * @param {function} [options.buttonAction] - Function to call when button is clicked (only works in parent context, not from iframe).
   * @param {object} [options.polygolappAction] - Action to send to a APP when button is clicked. Format: { appName, functionName, args }.
   * @param {boolean} [options.system] - Set to true for system notifications (hides app icon/title).
   */
  showNotification: function(message, options = {}) {
    // Note: 'buttonAction' functions cannot be passed from the iframe.
    // The parent window handles all actions.
    this._call('showNotification', [message, options]);
  },

    /**
     * Plays a system UI sound.
     * @param {string} type
     */
    playSound: function(type) {
        if (_systemSoundsAllowed) {
            this._call('playUiSound', [type]);
        }
    },

    /**
     * Configures the automatic UI sound detection for this APP.
     * Use this to disable automatic click sounds if you want to handle them manually.
     * @param {object} config
     * @param {boolean} config.auto - Set to false to disable auto-click detection.
     */
    configureSounds: function(config) {
        if (config && typeof config.auto === 'boolean') {
            _autoSoundEnabled = config.auto;
        }
    },

    /**
     * Sets the UI on the connected Waves remote (Second Screen).
     * @param {Array} components - Array of widget definitions.
     * Example: [{ type: 'button', id: 'btn1', label: 'Next Slide', icon: 'skip_next' }]
     */
    setRemoteUI: function(components) {
        this._call('setRemoteUI', [components]);
    },

    /**
     * Sends a partial update for specific components on the remote UI.
     * @param {object} updates - Key-value pairs where Key is the component ID and Value is the new value.
     */
    sendRemoteUpdate: function(updates) {
        this._call('sendRemoteUpdate', [updates]);
    },

    /**
     * Listen for actions triggered from the Waves remote.
     * @param {function} callback - Function to handle the event (id, value).
     */
    onRemoteAction: function(callback) {
        window.addEventListener('message', (event) => {
            if (event.source !== window.parent) return;
            if (event.data.type === 'remote-action') {
                callback(event.data.id, event.data.value);
            }
        });
    },

    /**
     * Listen for a request to refresh/send the remote UI.
     * Triggered when the app is launched via Mini Apps but is already running.
     * @param {function} callback - Function to execute (usually calling setRemoteUI).
     */
    onRequestRemoteUI: function(callback) {
        window.addEventListener('message', (event) => {
            if (event.source !== window.parent) return;
            if (event.data.type === 'requestRemoteUI') {
                callback();
            }
        });
    },

  /**
   * Requests a file upload from the user. 
   * In Polygol, this triggers both the local file picker and a request to the Waves Remote.
   * @param {object} options
   * @param {string} options.accept - MIME types (e.g., 'image/*', '.png').
   * @param {boolean} options.multiple - Allow multiple files.
   * @returns {Promise<File[]>} - Resolves with an array of File objects.
   */
  requestFile: function(options = {}) {
      const { accept = '*/*', multiple = false } = options;
      
      return new Promise((resolve, reject) => {
          if (!isInsidePolygol) {
              // Standalone Fallback: Create temporary input
              const input = document.createElement('input');
              input.type = 'file';
              input.accept = accept;
              input.multiple = multiple;
              input.style.display = 'none';
              
              input.onchange = (e) => {
                  if (e.target.files.length > 0) {
                      resolve(Array.from(e.target.files));
                  } else {
                      // User cancelled (hard to detect reliably, but we leave promise pending or handle via focus hack if needed)
                  }
                  input.remove();
              };
              document.body.appendChild(input);
              input.click();
          } else {
              // Polygol Mode: Request from Parent
              const requestId = `file_req_${++_dialogRequestId}`;
              _dialogCallbacks[requestId] = (filesData) => {
                  // Reconstruct File objects from data sent by parent
                  // filesData = [{ name, type, data (base64/blob), size }]
                  if (!filesData) return;
                  
                  const files = filesData.map(f => {
                      // Convert Base64 to Blob if necessary, or use existing blob
                      // Parent should send Blob/File if possible, but postMessage clones it.
                      if (f instanceof File) return f;
                      
                      // If data is base64 string
                      if (typeof f.data === 'string') {
                          const arr = f.data.split(',');
                          const bstr = atob(arr[1] || arr[0]);
                          let n = bstr.length;
                          const u8arr = new Uint8Array(n);
                          while (n--) u8arr[n] = bstr.charCodeAt(n);
                          return new File([u8arr], f.name, { type: f.type });
                      }
                      return null;
                  }).filter(f => f !== null);
                  
                  resolve(files);
              };
              
              this._call('requestFileUpload', [{ accept, multiple, requestId }]);
          }
      });
  },

  /**
   * Namespace for Live Activity functions.
   */
  liveActivity: {
    /**
     * Starts a Live Activity.
     * @param {object} options - Configuration object.
     * @param {string} options.activityId - A unique ID for this activity within your app.
     * @param {string} options.url - The URL of the HTML page for the activity's iframe.
     * @param {boolean} [options.homescreen=false] - Set to true if this activity should appear on the homescreen.
     * @param {boolean} [options.showInIsland=true] - Set to false to hide this from the Dynamic Area (Activity Island).
     * @param {string} [options.height='120px'] - The desired height of the activity in the notification shade.
     */
    start: function(options) {
      if (options && options.activityId) {
        _myActiveActivities.add(options.activityId); // Add to local tracker
      }
      const appName = document.body.dataset.appName || 'UnknownApp';
      Polygol._call('startLiveActivity', [appName, options]);
    },

    /**
     * Checks if a live activity with the given ID is currently active for this app.
     * @param {string} activityId - The unique ID of the activity.
     * @returns {boolean} - True if the activity is active, false otherwise.
     */
    isActive: function(activityId) {
      return _myActiveActivities.has(activityId);
    },

    /**
     * Pushes updated data to a running Live Activity.
     * The parent OS will forward this data to the correct iframe.
     * @param {string} activityId - The unique ID of the activity.
     * @param {object} data - The data payload to send (e.g., { timeLeft: 120 }).
     */
    update: function(activityId, data) {
      Polygol._call('updateLiveActivity', [activityId, data]);
    },

    /**
     * Stops a running Live Activity.
     * @param {string} activityId - The unique ID of the activity you want to stop.
     */
    stop: function(activityId) {
      if (activityId) {
        _myActiveActivities.delete(activityId); // Remove from local tracker
      }
      Polygol._call('stopLiveActivity', [activityId]);
    },
    
    /**
     * (For use inside a Live Activity iframe) Pushes updated summary data to the parent homescreen.
     * @param {object} data - The data to display.
     * @param {string} data.icon - The Material Symbols icon name.
     * @param {string} data.text - The text to display.
     */
    pushHomescreenUpdate: function(data) {
        if (isInsidePolygol) {
            window.parent.postMessage({
                type: 'live-activity-homescreen-update',
                icon: data.icon,
                text: data.text
            }, '*');
        }
    }
  },

  /**
   * Requests the parent window to minimize the current APP.
   */
  minimize: function() {
    this._call('minimizeFullscreenEmbed');
  },

  /**
   * Requests the parent to open another APP.
   * @param {string} url - The URL of the APP to open (e.g., "/chronos/index.html").
   */
  openApp: function(url) {
    this._call('createFullscreenEmbed', [url]);
  },

  /**
   * Turns the screen black for power-saving or privacy.
   */
  blackout: function() {
    this._call('blackoutScreen');
  },

  /**
   * Requests the system to enter or exit immersive mode.
   * In immersive mode, system UI handles are hidden. Swipe up from bottom to exit.
   * @param {boolean} enabled - True to enter, False to exit.
   */
  setImmersiveMode: function(enabled) {
      this._call('setImmersiveMode', [enabled]);
  },

  /**
   * Closes the current application (Fullscreen Embed).
   */
  close: function() {
    this._call('closeFullscreenEmbed');
  },

  /**
   * Checks if the system is currently in Silent Mode.
   * @returns {boolean}
   */
  isSilent: function() {
    return _isSilentMode;
  },

  /**
   * Uses the System TTS engine to speak text.
   * Bypasses browser autoplay policy.
   * @param {string} text - The text to speak.
   */
  speak: function(text) {
    this._call('speakText', [text]);
  },
 
   /**
   * Asks the parent Polygol to send back the list of currently installed apps.
   * The parent will respond with a 'installed-apps-list' message.
   */
  requestInstalledApps: function() {
   this._call('requestInstalledApps', []);
  },
   
  /**
  * Requests the parent Polygol to install a new APP.
  * @param {object} appObject - The complete app object with id, url, iconUrl, etc.
  */
  installApp: function(appObject) {
    this._call('installApp', [appObject]);
  },

  deleteApp: function(appObject) {
    this._call('deleteApp', [appObject]);
  },

  /**
   * Requests the parent Polygol to install a new App-Link.
   * @param {object} appLinkObject - The app-link object with name, url, iconUrl, etc.
   */
  installAppLink: function(appLinkObject) {
    this._call('installAppLink', [appLinkObject]);
  },

  /**
   * Registers a widget with the Polygol dashboard.
   * Apps should call this for each widget they provide.
   * @param {object} widgetData - An object describing the widget.
   * @param {string} widgetData.appName - The name of the app providing the widget.
   * @param {string} widgetData.widgetId - A unique ID for the widget (e.g., 'weather-current').
   * @param {string} widgetData.title - A user-friendly title (e.g., 'Current Weather').
   * @param {string} widgetData.url - The URL of the widget's content.
   * @param {Array<number>} widgetData.defaultSize - The default [width, height] in grid units (e.g., [1, 1]).
   * @param {string} [widgetData.openUrl] - Optional. The URL to open when the widget is tapped. Defaults to the app's main URL.
   */
  registerWidget: function(widgetData) {
    if (!widgetData || !widgetData.appName || !widgetData.widgetId || !widgetData.url || !widgetData.title) {
      console.error('[Polygol API] registerWidget requires appName, widgetId, url, and title.');
        return;
    }
    this._call('registerWidget', [widgetData]);
  },
    
  /**
   * Registers a new media session with the parent.
   * This will show the media widget in the Polygol UI.
   * @param {object} metadata - An object with { title, artist, artwork: [{src}] }.
   * @param {string[]} [supportedActions] - An array of supported actions, e.g., ['playPause', 'next', 'prev'].
   */
  registerMediaSession: function(metadata, supportedActions = ['playPause']) {
    const appName = document.body.dataset.appName || 'UnknownApp';
    // Pass the new 'supportedActions' array to the parent
    this._call('registerMediaSession', [appName, metadata, supportedActions]);
  },

  /**
   * Updates the parent Polygol with the current playback state.
   * @param {object} state - An object, e.g., { playbackState: 'playing' | 'paused', metadata: (optional) }.
   */
  updatePlaybackState: function(state) {
    const appName = document.body.dataset.appName || 'UnknownApp';
    this._call('updateMediaPlaybackState', [appName, state]);
  },

  /**
   * Tells the parent to clear/hide the media widget.
   */
  clearMediaSession: function() {
    const appName = document.body.dataset.appName || 'UnknownApp';
    this._call('clearMediaSession', [appName]);
  },

  updateMediaProgress: function(progressState) {
    const appName = document.body.dataset.appName || 'UnknownApp';
    this._call('updateMediaProgress', [appName, progressState]);
  },

  /**
   * Sets up listeners for media control actions sent FROM the parent.
   * @param {object} actions - An object with functions, e.g., { playPause: () => {...}, next: () => {...} }
   */
  onMediaControl: function(actions) {
    window.addEventListener('message', (event) => {
      if (event.source !== window.parent) return;
        if (event.data.type === 'media-control' && actions[event.data.action]) {
          actions[event.data.action]();
        }
    });
  },
      
  // --- NEW IndexedDB Functions ---
  listIDBDatabases: function() { this._call('listIDBDatabases'); },
  listIDBStores: function(dbName) { this._call('listIDBStores', [dbName]); },
  getIDBRecord: function(dbName, storeName, key) { this._call('getIDBRecord', [dbName, storeName, key]); },
  setIDBRecord: function(dbName, storeName, jsonData) { this._call('setIDBRecord', [dbName, storeName, jsonData]); },
  removeIDBRecord: function(dbName, storeName, key) { this._call('removeIDBRecord', [dbName, storeName, key]); },
  clearIDBStore: function(dbName, storeName) { this._call('clearIDBStore', [dbName, storeName]); },

  getLocalStorageItem: function(key) {
    this._call('getLocalStorageItem', [key]);
  },
  setLocalStorageItem: function(key, value) {
    this._call('setLocalStorageItem', [key, value]);
  },

  /**
   * Asks the parent Polygol to change a specific setting value.
   * This is the correct way for the settings app to apply changes.
   * @param {string} key - The localStorage key of the setting.
   * @param {string} value - The new value for the setting.
   */
  setSettingValue: function(key, value) {
    this._call('setLocalStorageItem', [key, value]);
  },

  /**
   * Asks the parent Polygol to check for a new service worker version
   * and trigger the update flow.
   */
  forceUpdate: function() {
    this._call('forceUpdatePolygol', []);
  },

  /**
   * Asks the parent to trigger a file download.
   * @param {string} filename - The desired name of the file.
   * @param {string} dataUrl - The content of the file as a data URL.
   */
  downloadFile: function(filename, dataUrl) {
    this._call('downloadFile', [filename, dataUrl]);
  },
  
  showAlert: function(message, title = null, icon = null) {
      return new Promise((resolve) => {
          const requestId = `alert_${++_dialogRequestId}`;
          _dialogCallbacks[requestId] = resolve;
          const defaultTitle = _t('INFO');
          this._call('showDialog', [{ type: 'alert', message, title: title || defaultTitle, icon, requestId }]);
      });
  },

  showConfirm: function(message, title = null, icon = null) {
      return new Promise((resolve) => {
          const requestId = `confirm_${++_dialogRequestId}`;
          _dialogCallbacks[requestId] = resolve;
          const defaultTitle = _t('CONFIRM');
          this._call('showDialog', [{ type: 'confirm', message, title: title || defaultTitle, icon, requestId }]);
      });
  },

  showPrompt: function(message, title = null, defaultValue = '', icon = null) {
      return new Promise((resolve) => {
          const requestId = `prompt_${++_dialogRequestId}`;
          _dialogCallbacks[requestId] = resolve;
          const defaultTitle = _t('PROMPT');
          this._call('showDialog', [{ type: 'prompt', message, title: title || defaultTitle, defaultValue, icon, requestId }]);
      });
  },

  /**
   * Listen for changes to the app's visibility (minimized vs restored).
   * @param {function} callback - Function that receives (isVisible: boolean)
   */
  onVisibilityChange: function(callback) {
      _onVisibilityChangeHandler = callback;
  },

  /**
   * Opens a bottom sheet with custom content.
   * @param {object} options
   * @param {string} [options.url] - URL to load in the sheet.
   * @param {string} [options.html] - Sandboxed HTML content to load.
   * @param {string} [options.height] - CSS height of the sheet (e.g., '60%').
   * @param {string[]} [options.styleUrls] - Array of stylesheet URLs to inject (for html mode).
   * @param {string} [options.styles] - Raw CSS string to inject (for html mode).
   */
  showSheet: function(options = {}) {
      this._call('showSheet', [options]);
  },

  /**
   * Closes the active bottom sheet.
   */
  closeSheet: function() {
      this._call('closeSheet');
  },

  /**
   * Registers an Activity Intent for the AI Voice Assistant.
   * @param {string} intentName - The name of the intent (e.g., 'play_music').
   * @param {Array} keywords - Array of trigger phrases (e.g., ['play music', 'start music']).
   * @param {function} callback - Function executed when the intent is triggered.
   */
  registerActivityIntent: function(intentName, keywords, callback) {
      _intentHandlers[intentName] = callback;
      this._call('registerActivityIntent', [{ intentName, keywords }]);
  },

  /**
   * Registers a Desktop Action that can be executed on files or globally.
   * @param {object} action { id, label, description, icon, handlerEvent }
   */
  registerAction: function(action) {
      this._call('registerDesktopAction', [action]);
  },

  /**
   * Gets a list of all registered Actions across all apps.
   * @returns {Promise<Array>}
   */
  listActions: function() {
      return new Promise((resolve) => {
          if (!isInsidePolygol) return resolve([]);
          const listener = (e) => {
              if (e.source !== window.parent) return;
              if (e.data.type === 'desktop-actions-list') {
                  window.removeEventListener('message', listener);
                  resolve(e.data.value || e.data.message || []);
              }
          };
          window.addEventListener('message', listener);
          this._call('listDesktopActions');
      });
  },

  /**
   * Executes a registered action, sending files to the handling app.
   */
  runActionOnFiles: function(actionId, filesArray) {
      this._call('runActionOnFiles', [actionId, filesArray]);
  },

  /**
   * Registers top-bar menus for this specific application.
   * @param {Array} menus Array of { id, label, items: [{id, label}] }
   */
  registerAppMenus: function(menus) {
      this._call('registerDesktopAppMenus', [menus]);
  },

  sheet: {
      /**
       * Send a message from the sheet to the origin application.
       * @param {any} data
       */
      sendToApp: function(data) {
          Polygol._call('sheetMessageToApp', [data]);
      },
      /**
       * Send a message from the origin application to the active sheet.
       * @param {any} data
       */
      sendToSheet: function(data) {
          Polygol._call('appMessageToSheet', [data]);
      },
      /**
       * Listen for messages (App listens for sheet, Sheet listens for app)
       * @param {function} callback
       */
      onMessage: function(callback) {
          window.addEventListener('message', (event) => {
              if (event.source !== window.parent) return;
              if (event.data.type === 'sheet-communication') {
                  callback(event.data.payload);
              }
          });
      }
  }
};

// --- Event Listener for Messages FROM Polygol ---

/**
 * Listens for messages from the parent window, such as theme
 * or animation setting changes, and applies them to the APP.
 */
window.addEventListener('message', async (event) => {
  if (event.source !== window.parent) {
    return;
  }

  const data = event.data;
  if (data && data.type) {
    switch (data.type) {
      case 'themeUpdate':
        document.body.classList.toggle('light-theme', data.theme === 'light');
        break;
      case 'themeVariablesUpdate':
        if (data.variables) {
            // Apply overrides
            Object.entries(data.variables).forEach(([key, val]) => {
                document.documentElement.style.setProperty(key, val);
            });
        } else {
            // Reset to defaults (remove overrides)
            const varsToRemove = [
                '--background-color-dark', '--background-color-dark-tr',
                '--modal-background-dark', '--modal-transparent-dark',
                '--search-background-dark', '--dark-overlay', '--dark-transparent', '--glass-border-dark',
                '--text-color-dark', '--secondary-text-color-dark', '--accent-dark', '--tonal-dark',
                
                '--background-color-light', '--background-color-light-tr',
                '--modal-background-light', '--modal-transparent-light',
                '--search-background-light', '--light-overlay', '--light-transparent', '--glass-border-light',
                '--text-color-light', '--secondary-text-color-light', '--accent-light', '--tonal-light',

                '--background-color-dark-highcontrast', '--background-color-dark-tr-highcontrast',
                '--modal-background-dark-highcontrast', '--modal-transparent-dark-highcontrast',
                '--search-background-dark-highcontrast', '--dark-overlay-highcontrast', '--dark-transparent-highcontrast',
                '--text-color-dark-highcontrast', '--secondary-text-color-dark-highcontrast', '--accent-dark-highcontrast', '--tonal-dark-highcontrast',
                
                '--background-color-light-highcontrast', '--background-color-light-tr-highcontrast',
                '--modal-background-light-highcontrast', '--modal-transparent-light-highcontrast',
                '--search-background-light-highcontrast', '--light-overlay-highcontrast', '--light-transparent-highcontrast',
                '--text-color-light-highcontrast', '--secondary-text-color-light-highcontrast', '--accent-light-highcontrast', '--tonal-light-highcontrast'
            ];
            varsToRemove.forEach(v => document.documentElement.style.removeProperty(v));
        }
        break;
      case 'animationsUpdate':
        document.body.classList.toggle('reduce-animations', !data.enabled);
        break;
      case 'contrastUpdate':
        document.documentElement.classList.toggle('polygol-high-contrast', data.enabled);
        break;
      case 'performanceProfileUpdate':
        window.systemPerformanceScore = data.score;
        window.isLowEndDevice = (data.score <= 2);
        break;
      case 'sunUpdate':
        document.documentElement.style.setProperty('--sun-shadow', data.shadow);
        document.documentElement.style.setProperty('--sun-shadow-strong', data.shadowStrong);
        break;
      case 'glassEffectsUpdate':
        const isOff = data.mode === 'off';
        const activeVal = data.val || 5;

        document.documentElement.style.setProperty('--blur0', isOff ? 'none' : `blur(${(activeVal * 0.2).toFixed(1)}px)`);
        document.documentElement.style.setProperty('--blur1', isOff ? 'none' : `blur(${(activeVal * 0.5).toFixed(1)}px)`);
        document.documentElement.style.setProperty('--blur2', isOff ? 'none' : `blur(${(activeVal * 1.0).toFixed(1)}px)`);
        document.documentElement.style.setProperty('--blur3', isOff ? 'none' : `blur(${(activeVal * 2.0).toFixed(1)}px)`);

        if (!isOff) {
            document.documentElement.classList.remove('polygol-trans-off', 'trans-off');
        } else {
            document.documentElement.classList.add('polygol-trans-off', 'trans-off');
        }
        
        document.documentElement.style.removeProperty('--fx-filter');
        document.documentElement.style.removeProperty('--edge-refraction-filter');
        break;
      case 'systemLayoutUpdate':
      case 'systemVariablesUpdate':
        if (data.variables) {
            _applySystemLayoutVariables(data.variables);
        }
        break;
      case 'localeUpdate':
        _applySystemLocale(data);
        break;
      case 'languageUpdate':
        if (data.languageCode) {
            _applySystemLocale({ languageCode: data.languageCode });
        }
        break;
      case 'dateFormatUpdate':
        if (data.dateFormat) {
            _applySystemLocale({ dateFormat: data.dateFormat });
        }
        break;
      case 'settingUpdate':
        if (data.key === 'polygolappSoundsEnabled') {
          _systemSoundsAllowed = (data.value === 'true');
        }
        if (data.key === 'silentMode') {
            _isSilentMode = (data.value === 'true');
        }
        if (data.key === 'keyboardNavEnabled') {
            KeyboardNavigationManager.setEnabled(data.value);
        }
        if (data.key === 'selectedLanguage') {
            _applySystemLocale({ languageCode: data.value });
        }
        if (data.key === 'systemDateFormat' || data.key === 'dateFormatPreference') {
            _applySystemLocale({ dateFormat: data.value });
        }
        if (data.key === 'use12HourFormat') {
            _applySystemLocale({ use12HourFormat: data.value });
        }
        if (data.key === 'timeZoneSelection') {
            _applySystemLocale({ timeZone: data.value });
        }
        break;
      case 'visibilityUpdate':
        _isSuspended = !data.visible;
        if (!_isSuspended && !_perfInterval) {
            _perfInterval = setInterval(reportPerformance, 30000);
        } else if (_isSuspended && _perfInterval) {
            clearInterval(_perfInterval);
            _perfInterval = null;
        }
        // Trigger user-defined handler
        if (typeof _onVisibilityChangeHandler === 'function') {
            _onVisibilityChangeHandler(data.visible);
        }
        break;
      case 'switch-control-enter':
          KeyboardNavigationManager.startNavigation(data.direction);
          break;
      case 'osk-insert':
        if (window._currentOskTarget) {
            const el = window._currentOskTarget;
            try {
                const start = el.selectionStart || 0;
                const end = el.selectionEnd || 0;
                const val = el.value || '';
                
                if (data.action === 'insert') {
                    el.value = val.slice(0, start) + data.key + val.slice(end);
                    el.selectionStart = el.selectionEnd = start + data.key.length;
                } else if (data.action === 'backspace') {
                    if (start === end && start > 0) {
                        el.value = val.slice(0, start - 1) + val.slice(end);
                        el.selectionStart = el.selectionEnd = start - 1;
                    } else if (start !== end) {
                        el.value = val.slice(0, start) + val.slice(end);
                        el.selectionStart = el.selectionEnd = start;
                    }
                } else if (data.action === 'replace-word') {
                    const len = data.length;
                    const word = data.word;
                    if (start >= len) {
                        el.value = val.slice(0, start - len) + word + ' ' + val.slice(end);
                        el.selectionStart = el.selectionEnd = start - len + word.length + 1;
                    }
                } else if (data.action === 'enter') {
                    // Properly synthesize KeyboardEvents for apps listening for Enter
                    const enterEventDown = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, key: 'Enter', code: 'Enter', keyCode: 13 });
                    el.dispatchEvent(enterEventDown);
                    el.dispatchEvent(new KeyboardEvent('keypress', { bubbles: true, cancelable: true, key: 'Enter', code: 'Enter', keyCode: 13 }));
                    el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, cancelable: true, key: 'Enter', code: 'Enter', keyCode: 13 }));

                    // If the app didn't preventDefault() to do its own action, execute default behaviors
                    if (!enterEventDown.defaultPrevented) {
                        if (el.tagName === 'TEXTAREA') {
                            el.value = val.slice(0, start) + '\n' + val.slice(end);
                            el.selectionStart = el.selectionEnd = start + 1;
                            el.dispatchEvent(new Event('input', { bubbles: true }));
                        } else {
                            if (el.form && el.form.requestSubmit) el.form.requestSubmit();
                            else if (el.form) el.form.submit();
                            el.blur();
                        }
                    } else {
                        if (el.tagName !== 'TEXTAREA') el.blur();
                    }
                }
            } catch (err) {
                // Fallback for inputs like type="email" or type="number" that block selection ranges
                if (data.action === 'insert') el.value += data.key;
                else if (data.action === 'backspace') el.value = el.value.slice(0, -1);
                else if (data.action === 'replace-word') el.value = el.value.slice(0, -data.length) + data.word + ' ';
                else if (data.action === 'enter') {
                    const enterEventDown = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, key: 'Enter', code: 'Enter', keyCode: 13 });
                    el.dispatchEvent(enterEventDown);
                    el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, cancelable: true, key: 'Enter', code: 'Enter', keyCode: 13 }));
                    if (!enterEventDown.defaultPrevented) {
                        if (el.form && el.form.requestSubmit) el.form.requestSubmit();
                        else if (el.form) el.form.submit();
                    }
                    el.blur();
                }
            }
            if (data.action !== 'enter') {
                el.dispatchEvent(new Event('input', { bubbles: true }));
                el.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }
        break;
      case 'forward-click': {
          const now = Date.now();
          if (typeof window._lastForwardClickTime === 'number' &&
              now - window._lastForwardClickTime < 300 &&
              Math.hypot(data.x - (window._lastForwardClickX || 0), data.y - (window._lastForwardClickY || 0)) < 30) {
              break;
          }
          window._lastForwardClickTime = now;
          window._lastForwardClickX = data.x;
          window._lastForwardClickY = data.y;

          // Catch forwarded taps from the parent OS handle zone
          const el = document.elementFromPoint(data.x, data.y);
          if (el) {
              if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
                  el.focus();
              } else {
                  const clickEvent = new MouseEvent('click', {
                      view: window,
                      bubbles: true,
                      cancelable: true,
                      clientX: data.x,
                      clientY: data.y
                  });
                  el.dispatchEvent(clickEvent);
              }
          }
          break;
      }
      case 'executeActivityIntent':
        if (data.intentName && _intentHandlers[data.intentName]) {
            _intentHandlers[data.intentName](data.parameters || {});
        }
        break;
      case 'dialog-response':
        if (data.requestId && _dialogCallbacks[data.requestId]) {
            _dialogCallbacks[data.requestId](data.value);
            delete _dialogCallbacks[data.requestId];
        }
        break;
      case 'ai-response':
        if (data.requestId && _aiCallbacks[data.requestId]) {
            if (data.error) {
                _aiCallbacks[data.requestId].reject(new Error(data.error));
            } else {
                _aiCallbacks[data.requestId].resolve(data.result);
            }
            delete _aiCallbacks[data.requestId];
        }
        break;
      case 'ai-ready-response':
        if (data.requestId && _aiCallbacks[data.requestId]) {
            _aiCallbacks[data.requestId].resolve(!!data.isReady);
            delete _aiCallbacks[data.requestId];
        }
        break;
      case 'volumeUpdate':
        const media = document.querySelectorAll('video, audio');
        if (data.muted === true || data.level === 0) {
            media.forEach(m => { m.muted = true; m.pause(); });
            if (window.AudioContext || window.webkitAudioContext) {
                const context = window._polygolAudioContext; 
                if (context && context.state !== 'suspended') context.suspend();
            }
        } else {
            media.forEach(m => { m.muted = false; });
        }

        const volEvent = new CustomEvent('PolygolVolumeChange', { 
            detail: { 
                level: data.level, 
                muted: data.muted
            } 
        });
        window.dispatchEvent(volEvent);
        break;
        
      // --- Handles screenshot requests from the parent ---
      case 'request-screenshot':
        if (window.isLowEndDevice) return; // Do not take screenshots on very low-end devices
        const _isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);

        // Helper function to perform the capture
        const doCapture = async () => {
            // Save current shadow state to prevent artifacts
            const root = document.documentElement;
            const originalShadow = root.style.getPropertyValue('--sun-shadow');
            const originalShadowStrong = root.style.getPropertyValue('--sun-shadow-strong');
            root.style.setProperty('--sun-shadow', 'none');
            root.style.setProperty('--sun-shadow-strong', 'none');

            try {
                const isLight = document.body.classList.contains('light-theme');
                const bgColor = isLight ? '#ffffff' : '#000000';
                let screenshotDataUrl;

                // Safely route to the loaded library based on platform context
                if (_isMobile && typeof html2canvas === 'function') {
                    const canvas = await html2canvas(document.body, {
                        backgroundColor: bgColor,
                        useCORS: true,
                        logging: false,
                        scale: 0.5
                    });
                    screenshotDataUrl = canvas.toDataURL('image/jpeg', 0.5);
                } else if (window.modernScreenshot) {
                    // Generate the screenshot of the app's content using modern-screenshot
                    screenshotDataUrl = await window.modernScreenshot.domToJpeg(document.body, {
                        backgroundColor: bgColor, // Explicitly set background
                        quality: 0.5,
                        filter: (node) => {
                            if (node.nodeType === 1 && (node.tagName === 'IMG' || node.tagName === 'VIDEO') && node.src && !node.src.startsWith('data:') && !node.src.startsWith('blob:')) {
                                try {
                                    const url = new URL(node.src, window.location.href);
                                    if (url.origin !== window.location.origin && !node.crossOrigin) return false;
                                } catch(e) {}
                            }
                            return true;
                        }
                    });
                } else {
                    throw new Error("Required screenshot library is not loaded.");
                }

                // Send the generated screenshot data back to the parent
                window.parent.postMessage({
                    type: 'screenshot-response',
                    screenshotDataUrl: screenshotDataUrl
                }, '*');
            } catch (e) {
                console.error("APP screenshot failed:", e);
            } finally {
                if (originalShadow) root.style.setProperty('--sun-shadow', originalShadow);
                if (originalShadowStrong) root.style.setProperty('--sun-shadow-strong', originalShadowStrong);
            }
        };

        const needsH2C = _isMobile && typeof html2canvas !== 'function';
        const needsMS = !_isMobile && typeof window.modernScreenshot === 'undefined';

        if (needsH2C) {
            const script = document.createElement('script');
            script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
            script.onload = () => doCapture();
            document.head.appendChild(script);
        } else if (needsMS) {
            const script = document.createElement('script');
            script.src = 'https://cdn.jsdelivr.net/npm/modern-screenshot@4.6.8/dist/index.min.js';
            script.onload = () => doCapture();
            document.head.appendChild(script);
        } else {
            doCapture();
        }
        break;
    }
  }
});

/**
 * On initial load, apply settings that might have been set by Polygol
 * in localStorage for a seamless appearance.
 */
document.addEventListener('DOMContentLoaded', () => {
  // NEW: Automatically request persistent storage for the APP
  if (navigator.storage && navigator.storage.persist) {
      navigator.storage.persist().then(granted => {
          if (granted) {
              console.log("[APP API] Persistent storage automatically granted.");
          } else {
              console.log("[APP API] Persistent storage not granted (Browser may manage eviction).");
          }
      }).catch(e => console.warn("[APP API] Storage persistence request failed:", e));
  }
    
  // Apply the 'standalone' class to the <html> element if not in Polygol
  if (!isInsidePolygol) {
      document.documentElement.classList.add('standalone');
  }

  try {
    // --- Theme Logic ---
    if (!isInsidePolygol) {
        // Standalone: Priority System Preference with Live Switching
        const mediaQuery = window.matchMedia('(prefers-color-scheme: light)');
        const updateTheme = (e) => {
            const isLight = e.matches;
            document.body.classList.toggle('light-theme', isLight);
            if (typeof updateSunEffect === 'function') {
                updateSunEffect();
            }
        };
        
        // Apply immediately and listen for changes
        updateTheme(mediaQuery);
        mediaQuery.addEventListener('change', updateTheme);
    } else {
        // Polygol: Use LocalStorage or Default
        let theme = localStorage.getItem('theme');
        if (theme === null) theme = 'dark';
        document.body.classList.toggle('light-theme', theme === 'light');
    }

    // --- Animation Logic ---
    let animValue = localStorage.getItem('animationsEnabled');
    let animationsEnabled = true;
    if (!isInsidePolygol && animValue === null) {
        // Standalone Default: System Preference (prefers-reduced-motion)
        animationsEnabled = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    } else {
        animationsEnabled = animValue !== 'false'; // Default true if null in Polygol
    }
    document.body.classList.toggle('reduce-animations', !animationsEnabled);

    // --- High Contrast Logic ---
    let contrastValue = localStorage.getItem('highContrast');
    let highContrastEnabled = false;
    if (!isInsidePolygol && contrastValue === null) {
        // Standalone Default: System Preference
        highContrastEnabled = window.matchMedia('(prefers-contrast: more)').matches;
    } else {
        highContrastEnabled = contrastValue === 'true';
    }

    document.documentElement.classList.toggle('polygol-high-contrast', highContrastEnabled);

    // --- System Locale & Layout Initialization ---
    let currentLang = localStorage.getItem('selectedLanguage');
    if (!currentLang || currentLang === 'auto') {
        currentLang = !isInsidePolygol ? _detectSystemLanguage() : _systemLocaleState.languageCode;
    }
    _applySystemLocale({
        languageCode: currentLang,
        dateFormat: localStorage.getItem('systemDateFormat') || localStorage.getItem('dateFormatPreference') || _systemLocaleState.dateFormat,
        use12HourFormat: localStorage.getItem('use12HourFormat') === 'true',
        timeZone: localStorage.getItem('timeZoneSelection') || _systemLocaleState.timeZone
    });

    if (!isInsidePolygol) {
        // Dynamic live language switching based on system
        window.addEventListener('languagechange', () => {
            const storedLang = localStorage.getItem('selectedLanguage');
            if (!storedLang || storedLang === 'auto') {
                const detected = _detectSystemLanguage();
                _applySystemLocale({ languageCode: detected });
            }
        });

        // Initialize standalone FxFilter and blur variables
        _initStandaloneFxFilter();

        // Initialize standalone SunShadow calculation and periodic refresh (every 60s)
        updateSunEffect();
        setInterval(updateSunEffect, 60000);
    }

    const cs = window.getComputedStyle ? window.getComputedStyle(document.documentElement) : null;
    if (cs) {
        const topP = cs.getPropertyValue('--top-screen-padding').trim();
        const bottomP = cs.getPropertyValue('--bottom-screen-padding').trim();
        const sideP = cs.getPropertyValue('--side-screen-padding').trim();
        if (topP || bottomP || sideP) {
            _applySystemLayoutVariables({
                '--top-screen-padding': topP || '80px',
                '--bottom-screen-padding': bottomP || '80px',
                '--side-screen-padding': sideP || '16px'
            });
        }
    }
  } catch (e) {
    console.error("APP: Could not access localStorage. Settings may not apply.", e);
  }

  // Handle initial silent mode state if sent via localStorage dump
  window.addEventListener('message', (event) => {
      if (event.data.type === 'localStorageItemValue' && event.data.key === 'silentMode') {
          _isSilentMode = (event.data.value === 'true');
      }
  });

  if (isInsidePolygol) {
    let lastActivitySignal = 0;
    const throttleInterval = 500; // Throttle messages to the parent

    const handleLocalActivity = () => {
        // Step 2: Notify the parent to reset the global hide timer (throttled).
        const now = Date.now();
        if (now - lastActivitySignal > throttleInterval) {
            window.parent.postMessage({ action: 'userActivity' }, '*');
            lastActivitySignal = now;
        }
    };
    
    // Listen for any user activity within this iframe.
    window.addEventListener('mousemove', handleLocalActivity);
    window.addEventListener('click', handleLocalActivity);
    window.addEventListener('keydown', handleLocalActivity);

    function getLocalSoundContext(element) {
        if (!element) return null;
        const tag = element.tagName;
        
        // Ignore Labels to prevent double sounds
        if (tag === 'LABEL') return null;

        const type = element.getAttribute('type');
        const role = element.getAttribute('role');

        if (tag === 'INPUT') {
            if (type === 'checkbox' || type === 'radio') return (role === 'switch') ? 'toggle' : 'check';
            if (type === 'range') return null;
            if (['text', 'password', 'email', 'number', 'search'].includes(type)) return 'type';
            return 'select';
        }
        if (tag === 'TEXTAREA') return 'type';
        if (tag === 'SELECT') return 'expand';
        if (tag === 'BUTTON' || tag === 'A' || role === 'button') return 'select';

        // Heuristic: Computed Pointer Cursor
        const style = window.getComputedStyle(element);
        if (style.cursor === 'pointer') return 'select';

        return null;
    }
      
    document.addEventListener('click', (e) => {
        if (!_autoSoundEnabled || !_systemSoundsAllowed) return;

        let target = e.target;
        let soundType = null;

        // Traverse up 5 levels to find interactive parent (e.g. span inside button)
        for (let i = 0; i < 5; i++) {
            if (!target || target === document) break;
            
            soundType = getLocalSoundContext(target);
            if (soundType) break;
            
            target = target.parentElement;
        }

        if (soundType) {
            Polygol.playSound(soundType);
        }
    }, { capture: true });

    // Input Focus Sounds
    document.addEventListener('focus', (e) => {
         if (!_autoSoundEnabled || !_systemSoundsAllowed) return;
         const type = getLocalSoundContext(e.target);
         if (type === 'type') {
             Polygol.playSound('type');
         }
    }, { capture: true });
  }

    // --- Performance Reporting ---
    _perfInterval = null;
    _isSuspended = true; // Apps start suspended until system focuses them

    function reportPerformance() {
        if (_isSuspended) return;
        
        if (performance.memory) {
            window.parent.postMessage({
                type: 'polygolapp-performance-report',
                appId: document.body.dataset.appName || 'Unknown',
                memory: performance.memory.usedJSHeapSize
            }, '*');
        }
    }

    // Handle system-driven visibility updates
    window.addEventListener('message', (e) => {
        if (e.source !== window.parent) return;
        if (e.data.type === 'visibilityUpdate') {
            _isSuspended = !e.data.visible;
            if (!_isSuspended && !_perfInterval) {
                _perfInterval = setInterval(reportPerformance, 30000); // 30s throttle
            } else if (_isSuspended && _perfInterval) {
                clearInterval(_perfInterval);
                _perfInterval = null;
            }
        }
    });
    
  // Announce API presence to enable full-screen mode and readiness for settings.
  if (isInsidePolygol) {
    window.parent.postMessage({ type: 'polygol-api-present' }, '*');
    window.parent.postMessage({ type: 'polygolapp-ready' }, '*');
  }

  // --- System Admin Listeners (Backup/Restore/Wipe) ---
  if (isInsidePolygol) {
      window.addEventListener('message', async (event) => {
          if (event.source !== window.parent) return;
          const data = event.data;
  
          // Helper: Blob to Base64
          const blobToBase64 = (blob) => {
              return new Promise((resolve, reject) => {
                  const reader = new FileReader();
                  reader.onloadend = () => resolve(reader.result);
                  reader.onerror = reject;
                  reader.readAsDataURL(blob);
              });
          };
  
          // Helper: Base64 to Blob
          const base64ToBlob = (dataUrl) => {
              const arr = dataUrl.split(',');
              const mime = arr[0].match(/:(.*?);/)[1];
              const bstr = atob(arr[1]);
              let n = bstr.length;
              const u8arr = new Uint8Array(n);
              while (n--) u8arr[n] = bstr.charCodeAt(n);
              return new Blob([u8arr], { type: mime });
          };
  
          if (data.type === 'admin-export') {
              try {
                  const exportPayload = { 
                      localStorage: { ...localStorage },
                      indexedDB: {} 
                  };
  
                  if (window.indexedDB && window.indexedDB.databases) {
                      const dbs = await window.indexedDB.databases();
                      for (const dbInfo of dbs) {
                          const dbName = dbInfo.name;
                          const db = await new Promise(r => {
                              const req = indexedDB.open(dbName);
                              req.onsuccess = () => r(req.result);
                          });
  
                          exportPayload.indexedDB[dbName] = { stores: {}, storeInfo: [] };
                          const storeNames = Array.from(db.objectStoreNames);
  
                          for (const sName of storeNames) {
                              const tx = db.transaction(sName, 'readonly');
                              const store = tx.objectStore(sName);
                              
                              // Save Schema Info
                              exportPayload.indexedDB[dbName].storeInfo.push({
                                  name: store.name,
                                  keyPath: store.keyPath,
                                  autoIncrement: store.autoIncrement,
                                  indexes: Array.from(store.indexNames).map(n => {
                                      const i = store.index(n);
                                      return { name: i.name, keyPath: i.keyPath, unique: i.unique };
                                  })
                              });
  
                              // Collect Records via Cursor
                              const records = [];
                              await new Promise(r => {
                                  store.openCursor().onsuccess = (e) => {
                                      const cursor = e.target.result;
                                      if (cursor) {
                                          records.push({ key: cursor.key, value: cursor.value });
                                          cursor.continue();
                                      } else { r(); }
                                  };
                              });
                              exportPayload.indexedDB[dbName].stores[sName] = records;
                          }
                          db.close();
                      }
                  }
  
                  window.parent.postMessage({
                      type: 'admin-export-response',
                      appUrl: window.location.href,
                      data: exportPayload
                  }, '*');
  
              } catch (e) {
                  console.error("Export failed", e);
                  window.parent.postMessage({ type: 'admin-export-response', error: e.message }, '*');
              }
          }
  
          if (data.type === 'admin-import') {
              try {
                  const { localStorage: lsData, indexedDB: idbData } = data.payload;
  
                  // 1. Restore LS
                  localStorage.clear();
                  for (const k in lsData) localStorage.setItem(k, lsData[k]);
  
                  // 2. Restore IDB
                  if (window.indexedDB && window.indexedDB.databases) {
                      const currentDbs = await window.indexedDB.databases();
                      for (const db of currentDbs) {
                          await new Promise(r => { const req = indexedDB.deleteDatabase(db.name); req.onsuccess = r; req.onerror = r; });
                      }
  
                      for (const dbName in idbData) {
                          const dbInfo = idbData[dbName];
                          const req = indexedDB.open(dbName);
                          
                          req.onupgradeneeded = (e) => {
                              const db = e.target.result;
                              dbInfo.storeInfo.forEach(s => {
                                  if (!db.objectStoreNames.contains(s.name)) {
                                      const store = db.createObjectStore(s.name, { keyPath: s.keyPath, autoIncrement: s.autoIncrement });
                                      if(s.indexes) s.indexes.forEach(idx => store.createIndex(idx.name, idx.keyPath, { unique: idx.unique, multiEntry: idx.multiEntry }));
                                  }
                              });
                          };
  
                          const db = await new Promise((res, rej) => {
                              req.onsuccess = () => res(req.result);
                              req.onerror = rej;
                          });
  
                          const tx = db.transaction(Object.keys(dbInfo.stores), 'readwrite');
                          for (const storeName in dbInfo.stores) {
                              const store = tx.objectStore(storeName);
                              const records = dbInfo.stores[storeName];
                              const sInfo = dbInfo.storeInfo.find(x => x.name === storeName);
                              
                              // Optimization: Clear store first to ensure clean overwrite
                              store.clear();
  
                              for (const rec of records) {
                                  let val = rec.value;
                                  let key = rec.key;
                                  
                                  // Legacy Base64 check
                                  if (val && val._isBlob && typeof val.data === 'string') val = base64ToBlob(val.data);
  
                                  try {
                                      // CRITICAL: If store has keyPath, don't provide key param
                                      // If store uses out-of-line keys, the key is required
                                      if (sInfo && (sInfo.keyPath !== null && sInfo.keyPath !== "")) {
                                          store.put(val);
                                      } else {
                                          store.put(val, key);
                                      }
                                  } catch (err) {
                                      console.error(`Store ${storeName} put failed:`, err);
                                  }
                              }
                          }
                          await new Promise(r => { tx.oncomplete = r; tx.onerror = r; });
                          db.close();
                      }
                  }
                  window.parent.postMessage({ type: 'admin-action-complete' }, '*');
              } catch (e) {
                  console.error("Import failed", e);
                  window.parent.postMessage({ type: 'admin-action-complete', error: e.message }, '*');
              }
          }
  
          if (data.type === 'admin-wipe') {
              try {
                  localStorage.clear();
                  sessionStorage.clear();
                  if (window.indexedDB && window.indexedDB.databases) {
                      const dbs = await window.indexedDB.databases();
                      for (const db of dbs) {
                          await new Promise(r => { 
                              const req = indexedDB.deleteDatabase(db.name); 
                              req.onsuccess = r; req.onerror = r; 
                          });
                      }
                  }
                  if ('serviceWorker' in navigator) {
                      const regs = await navigator.serviceWorker.getRegistrations();
                      for(const reg of regs) await reg.unregister();
                  }
                  window.parent.postMessage({ type: 'admin-action-complete' }, '*');
              } catch (e) {
                  window.parent.postMessage({ type: 'admin-action-complete', error: e.message }, '*');
              }
          }
      });
  }
});

// Expose APIs globally to APP context
window.Polygol = Polygol;
window.APPAPI = Polygol;
window.kirbAI = Polygol.ai;
window.GURAPP_STRINGS = _polygolappStrings;

// Announce that the API is ready
window.POLYGOL_API_READY = true;
const readyEvent = new CustomEvent('PolygolReady');
window.dispatchEvent(readyEvent);
